// Meanings of the Quran vocabulary (src/lib/vocab.ts) and its deck titles in every language of the website, keyed by
// word id. English and German stay in vocab.ts; Arabic readers get the short Arabic glosses of pagecontent/ar/vocab.ts.
// Short glosses in the Quranic sense of the word, names of Allah in the renderings established in each language.
// Synced to the app with mobile/scripts/sync-web.mjs. To add a language: add its code to VOCAB_LANGS and a value per word.
import AR_VOCAB, { decks as AR_DECKS } from "./pagecontent/ar/vocab";
import { VOCAB_DECKS, type Deck, type Word } from "./vocab";

export const VOCAB_LANGS = ["ar", "tr", "ur", "fa", "ps", "fr", "es", "id", "ms", "bn", "ru", "zh"] as const;
export type VocabLang = (typeof VOCAB_LANGS)[number];
type Other = Exclude<VocabLang, "ar">;

/** meaning of a word in the learner's language; English when the language has no entry */
export function meaning(w: Word, locale: string): string {
  if (locale === "de") return w.de;
  if (locale === "en") return w.en;
  return w.meanings?.[locale as VocabLang] ?? (locale === "ar" ? AR_VOCAB[w.id] : MEANINGS[w.id]?.[locale as Other]) ?? w.en;
}

/** all meanings of a word (for vocabFor) */
export function meaningsOf(id: string): Partial<Record<VocabLang, string>> {
  const m: Partial<Record<VocabLang, string>> = { ...(MEANINGS[id] ?? {}) };
  if (AR_VOCAB[id]) m.ar = AR_VOCAB[id];
  return m;
}

export function deckTitle(d: Deck, locale: string): string {
  if (locale === "de") return d.title_de;
  return (locale === "ar" ? AR_DECKS[d.id]?.title : DECKS[d.id]?.[locale as Other]?.[0]) ?? d.title_en;
}
export function deckDesc(d: Deck, locale: string): string {
  if (locale === "de") return d.desc_de;
  return (locale === "ar" ? AR_DECKS[d.id]?.desc : DECKS[d.id]?.[locale as Other]?.[1]) ?? d.desc_en;
}

