/** the decks with every word's meanings attached (titles: deckTitle / deckDesc) */
export function vocabFor(locale: string): Deck[] {
  void locale; // all languages are attached, so a language switch needs no reload
  return DECKS_WITH_MEANINGS;
}
const DECKS_WITH_MEANINGS: Deck[] = VOCAB_DECKS.map((d) => ({ ...d, words: d.words.map((w) => ({ ...w, meanings: meaningsOf(w.id) })) }));
